# CSP: no enemies adjacent
enemies = {"Alice": {"Bob"}, "Bob": {"Alice", "Charlie"}, "Charlie": {"Bob"}}
seats = ["Alice", "Charlie", "Bob"]
for i in range(len(seats)-1):
    if seats[i+1] in enemies[seats[i]]:
        print(f"Conflict at positions {i},{i+1}")
        break
else:
    print("No seating conflicts!")
